#[derive(Clone,Debug,PartialEq,Eq)]pub struct Site{pub id:String,pub enzyme:String,pub position:u16,pub forward:bool}
#[derive(Clone,Debug)]pub struct SiteDomain{pub id:String,pub enzyme:String,pub options:Vec<(u16,bool)>}
#[derive(Clone,Debug)]pub struct Digest{pub enzymes:Vec<String>,pub fragments:Vec<u16>,pub tolerance:u16}
#[derive(Clone,Debug)]pub struct Junction{pub a:String,pub b:String,pub same_orientation:bool}
#[derive(Clone,Debug)]pub struct Input{pub length:u16,pub domains:Vec<SiteDomain>,pub digests:Vec<Digest>,pub junctions:Vec<Junction>}
pub fn digest(l:u16,m:&[Site],es:&[String])->Vec<u16>{let mut p:Vec<_>=m.iter().filter(|s|es.contains(&s.enzyme)).map(|s|s.position).collect();p.sort();p.dedup();if p.is_empty(){return vec![]}if p.len()==1{return vec![l]}let mut o=Vec::new();for i in 0..p.len(){o.push(if i+1<p.len(){p[i+1]-p[i]}else{l-p[i]+p[0]})}o.sort();o}
fn canonical(l:u16,m:&[Site])->(String,Vec<Site>){let mut best:Option<(String,Vec<Site>)>=None;for rev in [false,true]{let t:Vec<Site>=m.iter().map(|s|Site{id:s.id.clone(),enzyme:s.enzyme.clone(),position:if rev{(l-s.position)%l}else{s.position},forward:if rev{!s.forward}else{s.forward}}).collect();for anchor in &t{let mut q:Vec<Site>=t.iter().map(|s|Site{id:s.id.clone(),enzyme:s.enzyme.clone(),position:(s.position+l-anchor.position)%l,forward:s.forward}).collect();q.sort_by_key(|s|(s.position,s.id.clone()));let key=q.iter().map(|s|format!("{:05}:{}:{}:{}",s.position,s.id,s.enzyme,if s.forward{'F'}else{'R'})).collect::<Vec<_>>().join("|");if best.as_ref().map_or(true,|x|key<x.0){best=Some((key,q))}}}best.unwrap()}
fn score(i:&Input,m:&[Site])->(usize,u64,usize){let(mut miss,mut err)=(0,0u64);for d in &i.digests{let a=digest(i.length,m,&d.enzymes);let mut b=d.fragments.clone();b.sort();miss+=a.len().abs_diff(b.len());for(x,y)in a.iter().zip(&b){let e=x.abs_diff(*y);if e>d.tolerance{miss+=1}else{err+=e as u64}}}let mut order=m.to_vec();order.sort_by_key(|s|s.position);let mut bad=0;for j in &i.junctions{let a=order.iter().position(|s|s.id==j.a);let b=order.iter().position(|s|s.id==j.b);match(a,b){(Some(x),Some(y))=>{let adjacent=(x+1)%order.len()==y||(y+1)%order.len()==x;if !adjacent||(order[x].forward==order[y].forward)!=j.same_orientation{bad+=1}},_=>bad+=1}}(miss,err,bad)}
fn walk(i:&Input,k:usize,m:&mut Vec<Site>,best:&mut Option<((usize,u64,usize,String),Vec<Site>)>){if k==i.domains.len(){let mut p:Vec<_>=m.iter().map(|s|s.position).collect();p.sort();p.dedup();if p.len()!=m.len(){return}let(a,b,c)=score(i,m);let(key,canon)=canonical(i.length,m);let rank=(a,b,c,key);if best.as_ref().map_or(true,|x|rank<x.0){*best=Some((rank,canon))}return}let d=&i.domains[k];for &(position,forward)in &d.options{if position<i.length{m.push(Site{id:d.id.clone(),enzyme:d.enzyme.clone(),position,forward});walk(i,k+1,m,best);m.pop();}}}
pub fn reconstruct(i:&Input)->Option<Vec<Site>>{if i.length==0||i.domains.is_empty()||i.domains.iter().any(|d|d.options.is_empty()){return None}let mut b=None;walk(i,0,&mut Vec::new(),&mut b);b.map(|x|x.1)}
